async function supervisor() {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-sdk-build-revision-'));
  roots.push(root);
  const project = path.join(root, 'project');
  await fs.mkdir(project);
  await writeProjectConfig(project, defaultProjectConfig('docs', 'en'));
  const name = 'build-revision';
  const change = path.join(project, 'docs/comet/changes', name);
  await fs.mkdir(path.join(change, 'specs/workflow'), { recursive: true });
  await fs.writeFile(
    path.join(change, 'brief.md'),
    '# Outcome\nShip the workflow.\n# Scope\nTwo children.\n## Directory structure\n### Created\n- left.txt — implement the left child.\n- right.txt — implement the right child.\n# Non-goals\nPublishing.\n# Acceptance examples\n- The workflow resumes.\n',
  );
  await fs.writeFile(
    path.join(change, 'specs/workflow/spec.md'),
    '# Workflow\nThe workflow resumes.\n',
  );
  await fs.writeFile(
    path.join(change, 'children.yaml'),
    'schema: comet.native.children.v2\nacceptance_index:\n  A1:\n    source: brief.md\n    text: The workflow resumes.\nchildren:\n  - name: left\n    depends_on: []\n    covers: [A1]\n  - name: right\n    depends_on: [left]\n    covers: [A1]\n',
  );
  await fs.writeFile(
    path.join(project, '.gitignore'),
    '.comet/runtime/\n.comet/current-change.json\n.worktrees/\n**/comet-state.yaml\n**/verification.md\n',
  );
  const git = (cwd: string, argv: string[]) =>
    execFileSync(
      'git',
      ['-c', 'user.name=Comet Test', '-c', 'user.email=comet-test@example.com', ...argv],
      { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] },
    ).trim();
  git(project, ['init', '-b', 'main']);
  git(project, ['add', '.']);
  git(project, ['commit', '-m', 'base']);
  const targetCommit = git(project, ['rev-parse', 'HEAD']);
  git(project, ['config', 'user.name', 'Comet Test']);
  git(project, ['config', 'user.email', 'comet-test@example.com']);
  const candidateCli =
    process.env.COMET_NATIVE_CANDIDATE_CLI ?? path.resolve('dist/app/cli/index.js');
  const baselineCli = process.env.COMET_NATIVE_BASELINE_CLI ?? candidateCli;
  function cli(argv: string[], file = candidateCli, projectRoot = project) {
    const result = spawnSync(
      process.execPath,
      [file, ...argv, ...(argv.includes('--project-root') ? [] : ['--project-root', projectRoot])],
      {
        encoding: 'utf8',
        timeout: 60000,
        // 完整历史可超过默认 1 MiB；只有显式详情使用更大的有限缓冲。
        ...(argv.includes('--details') ? { maxBuffer: 4 * 1024 * 1024 } : {}),
      },
    );
    if (result.error) throw result.error;
    if (!result.stdout.trim())
      throw new Error(
        `Native CLI returned no JSON: ${JSON.stringify({ status: result.status, signal: result.signal, stderr: result.stderr })}`,
      );
    return {
      exitCode: result.status,
      response: JSON.parse(result.stdout),
      stderr: result.stderr,
      stdoutBytes: Buffer.byteLength(result.stdout),
    };
  }
  let sequence = 0;
  async function dispatchResult(request: Record<string, unknown>, file = candidateCli) {
    const requestFile = path.join(root, `request-${++sequence}.json`);
    await fs.writeFile(requestFile, JSON.stringify(request));
    return cli(
      [
        'runtime',
        'dispatch',
        '--application',
        'native',
        '--request',
        requestFile,
        ...(file === candidateCli ? ['--details'] : []),
      ],
      file,
    );
  }
  async function dispatch(
    request: Record<string, unknown>,
    file = candidateCli,
  ): Promise<WorkflowRun> {
    const result = await dispatchResult(request, file);
    if (result.exitCode !== 0) throw new Error(JSON.stringify(result));
    if (Array.isArray(result.response.data?.actions)) return result.response.data;
    if (file === candidateCli || request.operation === 'inspect')
      throw new Error(`CLI did not return the requested complete Run: ${JSON.stringify(result)}`);
    // 旧 CLI 可能返回 compact Action；不假定它支持 --details，另用 inspect 读取权威 Run。
    const inspected = await dispatchResult({ operation: 'inspect', runId: name }, file);
    if (inspected.exitCode !== 0 || !Array.isArray(inspected.response.data?.actions))
      throw new Error(JSON.stringify(inspected));
    return inspected.response.data;
  }
  const started = await dispatch(
    {
      operation: 'start',
      runId: name,
      workflow: { id: 'comet-native', version: '4' },
      input: { name, artifactRootRef: 'docs' },
      initialState: createNativePortableState({
        name,
        language: 'en',
        workspace: {
          isolation: 'current',
          change_branch: 'main',
          target_branch: 'main',
          finish: null,
        },
      }),
    },
    baselineCli,
  );
  expect(cli(['native', 'next', name, '--json'], baselineCli).exitCode).toBe(0);
  const proposal = await dispatch({ operation: 'inspect', runId: name }, baselineCli);
  const confirmed = cli(
    [
      'native',
      'next',
      name,
      '--confirmed',
      '--summary',
      'Confirmed full child scope',
      '--expected-state-version',
      String((proposal.state as { state_version: number }).state_version),
      '--expected-action',
      'confirm-shape',
      '--coordination-mode',
      'multi-session',
      '--json',
    ],
    baselineCli,
  );
  expect(confirmed.response).not.toHaveProperty('error');
  let run = await dispatch({ operation: 'inspect', runId: name }, baselineCli);
  for (
    let count = 0;
    count < 5 &&
    !run.actions.some((a) => a.stepId === 'supervisor.child.builder' && a.status === 'pending');
    count++
  ) {
    const next = cli(['native', 'next', name, '--json'], baselineCli);
    if (next.exitCode !== 0) throw new Error(JSON.stringify(next));
    run = await dispatch({ operation: 'inspect', runId: name }, baselineCli);
  }
  expect(run.actions.at(-1)).toMatchObject({
    stepId: 'supervisor.child.builder',
    status: 'pending',
  });
  const inspect = (file = candidateCli) => dispatch({ operation: 'inspect', runId: name }, file);
  const next = async (file = candidateCli): Promise<WorkflowRun> => {
    const result = cli(['native', 'next', name, '--json'], file);
    if (result.exitCode !== 0) {
      const inspected = await inspect(file);
      throw new Error(
        JSON.stringify({
          result,
          unresolved: inspected.actions
            .filter((action) => action.status === 'unknown' || action.status === 'failed')
            .map(({ id, stepId, reason }) => ({ id, stepId, reason })),
        }),
      );
    }
    const inspected = await inspect(file);
    // 归档属于子任务集成收尾，完成它后再读取下一项工作。
    if (
      inspected.actions.some(
        (action) => action.stepId === 'supervisor.child.archive' && action.status === 'pending',
      )
    ) {
      return next(file);
    }
    return inspected;
  };
  const pending = (value: WorkflowRun, step: string) =>
    value.actions.find((a) => a.stepId === step && a.status === 'pending')!;
  const claim = (action: RuntimeAction, file = candidateCli) =>
    dispatch(
      {
        operation: 'claim',
        runId: name,
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        executorId: 'native-host',
        sessionId: action.id + '-session',
        claimToken: action.id + '-claim',
      },
      file,
    );
  const report = (action: RuntimeAction, output: unknown, file = candidateCli) => {
    const value = output as {
      verificationChecks?: Array<{
        name: string;
        executable: string;
        argv: string[];
        cwdRef: string;
      }>;
      checks?: unknown;
      response?: unknown;
    };
    if (value.verificationChecks) {
      const activation = (
        action.input as {
          activation?: { worktree?: string; integrationWorktree?: string };
        }
      ).activation;
      const worktree = activation?.worktree ?? activation?.integrationWorktree ?? project;
      const observed = value.verificationChecks.map((plan) => {
        const actual = spawnSync(plan.executable, plan.argv, {
          cwd: path.resolve(worktree, plan.cwdRef),
          windowsHide: true,
        });
        expect(actual.status).toBe(0);
        return {
          name: plan.name,
          result: 'passed',
          note: 'Actual Agent platform Node command exited 0; SIMULATED report, no Eval.',
        };
      });
      output = { ...value, verificationChecks: undefined, checks: observed };
      delete (output as { verificationChecks?: unknown }).verificationChecks;
    } else if (value.response && !value.checks) output = { ...value, checks: [] };
    return dispatch(
      {
        operation: 'record-outcome',
        runId: name,
        outcome: {
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          claimToken: action.claim!.token,
          outcomeId: action.id + '-result',
          status: 'succeeded',
          output,
        },
      },
      file,
    );
  };
  const checkPlan = (child: string) => [
    {
      id: 'artifact-' + child,
      name: 'Read actual ' + child + ' artifact',
      executable: process.execPath,
      argv: [
        '-e',
        `const fs=require('node:fs');if(fs.readFileSync('${child}.txt','utf8').trim()!=='approved')process.exit(1);`,
      ],
      cwdRef: '.',
      timeoutMs: 10000,
      repeatable: true,
    },
  ];
  async function submitChild(value: WorkflowRun, file = candidateCli, includeBase = false) {
    const builder = pending(value, 'supervisor.child.builder');
    const input = (
      builder.input as {
        activation: { child: string; worktree: string; baseCommit: string };
      }
    ).activation;
    if (includeBase) git(input.worktree, ['merge', '--ff-only', input.baseCommit]);
    await fs.writeFile(path.join(input.worktree, input.child + '.txt'), 'approved\n');
    git(input.worktree, ['add', input.child + '.txt']);
    git(input.worktree, ['commit', '--allow-empty', '-m', builder.id + ' candidate']);
    const claimed = await claim(builder, file);
    return report(
      claimed.actions.find((a) => a.id === builder.id)!,
      {
        summary: 'Actual candidate',
        candidateCommit: git(input.worktree, ['rev-parse', 'HEAD']),
        verificationChecks: checkPlan(input.child),
      },
      file,
    );
  }
  async function verifyChild(value: WorkflowRun, file = candidateCli) {
    const verifier = pending(value, 'supervisor.child.verifier');
    const input = (
      verifier.input as {
        activation: {
          child: string;
          worktree: string;
          candidateCommit: string;
        };
      }
    ).activation;
    expect(
      (await fs.readFile(path.join(input.worktree, input.child + '.txt'), 'utf8')).trim(),
    ).toBe('approved');
    const claimed = await claim(verifier, file);
    return report(
      claimed.actions.find((a) => a.id === verifier.id)!,
      {
        candidateCommit: input.candidateCommit,
        verdict: 'pass',
        evidence: {
          summary: 'Distinct test executor inspected actual artifact',
          checks: [
            {
              name: 'Actual ' + input.child + ' artifact',
              result: 'passed',
              note: 'Agent read actual committed Child file.',
            },
          ],
          acceptance: [{ id: 'A1', result: 'passed', reason: 'Actual artifact read' }],
        },
      },
      file,
    );
  }
  const revise = (value: WorkflowRun) =>
    cli([
      'native',
      'next',
      name,
      '--revise-requirements',
      '--summary',
      'User narrows actual host acceptance to Claude Code; product Codex support remains.',
      '--expected-state-version',
      String((value.state as { state_version: number }).state_version),
      '--expected-action',
      'revise-requirements',
      '--json',
    ]);
  async function confirmAgain() {
    const proposal = await next();
    const confirmed = cli([
      'native',
      'next',
      name,
      '--confirmed',
      '--summary',
      'Confirmed changed host acceptance and retained product support',
      '--expected-state-version',
      String((proposal.state as { state_version: number }).state_version),
      '--expected-action',
      'confirm-shape',
      '--coordination-mode',
      'multi-session',
      '--json',
    ]);
    if (confirmed.exitCode !== 0) throw new Error(JSON.stringify(confirmed));
    return inspect();
  }
  async function archiveSnapshot(value: WorkflowRun, child: string) {
    const archive = value.actions.findLast(
      (action) =>
        action.stepId === 'supervisor.child.archive' &&
        action.status === 'succeeded' &&
        (action.outcome?.output as { child?: string } | null)?.child === child,
    )!;
    const receipt = archive.outcome!.output as {
      archiveRef: string;
      archiveCommit: string;
    };
    const integration = path.join(project, '.worktrees', name + '-integration');
    const relative = 'docs/comet/archive/' + receipt.archiveRef;
    const directory = path.join(integration, relative);
    const files = Object.fromEntries(
      await Promise.all(
        ['brief.md', 'spec.md', 'archive-source.md', 'comet-state.yaml', 'verification.md'].map(
          async (ref) => [ref, await fs.readFile(path.join(directory, ref))] as const,
        ),
      ),
    );
    const committedFiles = Object.fromEntries(
      Object.keys(files).map((ref) => [
        ref,
        execFileSync('git', ['show', receipt.archiveCommit + ':' + relative + '/' + ref], {
          cwd: integration,
          stdio: ['ignore', 'pipe', 'pipe'],
        }),
      ]),
    );
    return {
      archive,
      receipt,
      integration,
      relative,
      directory,
      files,
      committedFiles,
    };
  }
  const restoreArchiveMaterials = (value: WorkflowRun, targetProjectRoot: string, dryRun = true) =>
    backfillNativeSdkSupervisorChildArchiveMaterials({
      projectRoot: project,
      targetProjectRoot,
      parent: name,
      expectedRevision: value.revision,
      dryRun,
    });
  function expectArchiveHistory(snapshot: Awaited<ReturnType<typeof archiveSnapshot>>) {
    for (const [ref, bytes] of Object.entries(snapshot.committedFiles))
      expect(
        execFileSync(
          'git',
          ['show', snapshot.receipt.archiveCommit + ':' + snapshot.relative + '/' + ref],
          {
            cwd: project,
          },
        ),
      ).toEqual(bytes);
  }
  return {
    root,
    project,
    change,
    name,
    run,
    started,
    git,
    cli,
    dispatch,
    dispatchResult,
    inspect,
    next,
    pending,
    claim,
    report,
    checkPlan,
    submitChild,
    verifyChild,
    revise,
    confirmAgain,
    baselineCli,
    targetCommit,
    archiveSnapshot,
    restoreArchiveMaterials,
    expectArchiveHistory,
  };
}

it('revises the original Supervisor Build after an independent Child reports blocked through the public CLI', async () => {
  const f = await supervisor();
  await f.submitChild(f.run, f.baselineCli);
  let run = await f.next(f.baselineCli);
  const verifier = f.pending(run, 'supervisor.child.verifier');
  const activation = verifier.input as {
    activation: { candidateCommit: string };
  };
  run = await f.claim(verifier, f.baselineCli);
  run = await f.report(
    run.actions.find((action) => action.id === verifier.id)!,
    {
      candidateCommit: activation.activation.candidateCommit,
      verdict: 'blocked',
      evidence: {
        summary: 'External host evidence has not been supplied',
        checks: [],
        acceptance: [
          {
            id: 'A1',
            result: 'blocked',
            reason: 'External host evidence is missing',
          },
        ],
      },
    },
    f.baselineCli,
  );
  const revised = f.revise(run);
  expect(revised.exitCode, JSON.stringify(revised.response)).toBe(0);
  const revisedRun = await f.inspect();
  expect(revisedRun.runId).toBe(run.runId);
  expect(revisedRun.definitionHashes).toEqual(run.definitionHashes);
  expect(revisedRun.state).toMatchObject({ phase: 'shape', status: 'active' });
  const settled = run.actions.filter((action) => action.status !== 'pending');
  expect(
    revisedRun.actions.filter((action) => settled.some((old) => old.id === action.id)),
  ).toEqual(settled);
}, 180000);

