  );
  expect(f.git(integration, ['rev-parse', 'HEAD'])).toBe(integratedHead);
  const builder = f.pending(run, 'supervisor.child.builder');
  expect(builder.id).not.toBe(failedBuilder.id);
  expect(builder.input).toMatchObject({
