  const freshBuilder = [...run.actions]
    .reverse()
    .find((a) => a.stepId === 'supervisor.child.builder' && a.status === 'succeeded')!;
  expect(freshBuilder.id).not.toBe(originalChecks.id);
  expect(freshBuilder.outcome?.output).toMatchObject({
